-- WA alpine/mountaineering route audit: batch 293 (pass 5)
-- Date: 2026-09-18
-- Routes: wa_sherman_peak_baker_route, wa_sherman_peak_baker_squak_glacier,
--         wa_sherpa_balanced_rock_ne_couloir, wa_sherpa_glacier, wa_sherpa_peak_east_ridge,
--         wa_sherpa_peak_north_ridge, wa_sherpa_peak_west_ridge, wa_silver_star_glacier
-- Plus 5 out-of-batch cross-reference fixes on Colfax Peak / Hadley Peak routes (see comments).
-- Review before applying. No DELETE statements. No coordinates invented anywhere in this file --
-- every corrected value is copied from a verified sibling field on the same row, a sibling
-- route sharing the identical trailhead, this row's own itinerary/loss_ft arithmetic, or an
-- external source (WTA, cited inline) cross-checked against this row's own gain_ft.

BEGIN;

-- wa_sherman_peak_baker_route (Crater Rim Scramble / Easton Glacier): bivy pruned 6->2. Four entries described camps for Hadley Peak (Cougar Divide, Skyline Divide, Deadhorse Creek basin -- all explicitly 'the north-side approach to Hadley Peak') and for Colfax Peak's north-side ice routes (Coleman Glacier bivy, explicitly 'Colfax's three north-side ice lines') -- a corridor-wide bivy array shared verbatim across Sherman Peak (Mount Baker), Colfax Peak and Hadley Peak, three different peaks in the same wa_shuksan_baker_neighbors region. Kept the two entries that explicitly name Sherman Peak's own Squak Glacier route.
UPDATE routes SET bivy = '[{"elev": 6500, "name": "Crag View, Squak Glacier", "type": "camp", "notes": "This is the camp for Sherman Peak''s Squak Glacier route and it is the site the Mount Baker file does not cover, since everything written there is on the Easton or the Coleman. It sits about 3.5 miles and 3,300 ft above Schriebers Meadow: the Park Butte trail past Sulphur Creek and the meadows, then a climbers'' path leaving the trail around 4,600 ft and running up onto the moraine. From here the route makes a rising traverse of the Squak toward Sherman''s south ridge, roughly 3,600 ft to the summit. The Squak is an early-season objective and the reason is specific — a bergschrund opens across the line as the season goes on and can shut the route down entirely by late summer, so a July plan is a different proposition from a May one. The lower part of the approach is outside the wilderness and carries snowmobile traffic into early July. Forest Road 13 off Road 12 is gravel and holds snow late; check it before a long drive.", "water": "No potable water at the trailhead or anywhere on the route. Melt channels run near the moraine edge in early summer and are gone or unreliable by August, so plan on melting snow and carry the fuel for it.", "permit": "Mt Baker-Snoqualmie National Forest, Mount Baker Wilderness. No climbing permit and no overnight backcountry permit, but camping below 6,000 ft on this route is prohibited, which is the practical reason Crag View exists where it does. A recreation pass is required to park at the Park Butte trailhead. Party size is capped at 12 once you enter the wilderness, campfires are prohibited, and there is no toilet anywhere on the route — carry blue bags, which are handed out free at the ranger offices in Sedro-Woolley and at Glacier. Nothing may be buried in snow or dropped into a crevasse or moat.", "capacity": "The established climbers'' camp on the Squak, with room for several parties on gravel benches and snow platforms at the toe of the glacier; quieter than the Easton side even on a summer weekend"}, {"elev": 7000, "name": "Upper Squak benches, Sulphur moraine and the rock prow", "type": "bivy", "notes": "Parties who want Sherman''s summit day short move above Crag View and camp on the Sulphur moraine at the glacier''s edge around 7,000 ft, or push on to the flatter ground below the rock prow closer to 7,600 ft. The gain is real, since it takes a good chunk out of the traverse to the south ridge and puts you at the base of the steep snow with the night''s freeze still holding. The cost is a fully exposed camp on a volcano''s south flank, where wind is the usual reason parties come back down to Crag View, and you are already on glacier and roped to get here. Camping this high also means committing to melt water, which drives fuel weight up. Where exactly the platforms are usable moves year to year with the crevasse pattern, so arrive with daylight to scout rather than in the dark.", "water": "None. Melt snow. Anything running here in early summer is a bonus and will not be there later in the year.", "permit": "Mount Baker Wilderness rules as at Crag View — no permit to camp, recreation pass at the Park Butte trailhead, 12-person party limit, no campfires, all waste packed out in blue bags.", "capacity": "Dug snow platforms and moraine gravel for one or two parties along the right-hand edge of the glacier, with a second bench under a rock prow several hundred feet higher; no established sites and no shelter"}]'::jsonb WHERE id = 'wa_sherman_peak_baker_route';

-- wa_sherman_peak_baker_squak_glacier (Squak Glacier Route): bivy pruned 6->2, same corridor contamination as the sibling Easton Glacier route above.
UPDATE routes SET bivy = '[{"elev": 6500, "name": "Crag View, Squak Glacier", "type": "camp", "notes": "This is the camp for Sherman Peak''s Squak Glacier route and it is the site the Mount Baker file does not cover, since everything written there is on the Easton or the Coleman. It sits about 3.5 miles and 3,300 ft above Schriebers Meadow: the Park Butte trail past Sulphur Creek and the meadows, then a climbers'' path leaving the trail around 4,600 ft and running up onto the moraine. From here the route makes a rising traverse of the Squak toward Sherman''s south ridge, roughly 3,600 ft to the summit. The Squak is an early-season objective and the reason is specific — a bergschrund opens across the line as the season goes on and can shut the route down entirely by late summer, so a July plan is a different proposition from a May one. The lower part of the approach is outside the wilderness and carries snowmobile traffic into early July. Forest Road 13 off Road 12 is gravel and holds snow late; check it before a long drive.", "water": "No potable water at the trailhead or anywhere on the route. Melt channels run near the moraine edge in early summer and are gone or unreliable by August, so plan on melting snow and carry the fuel for it.", "permit": "Mt Baker-Snoqualmie National Forest, Mount Baker Wilderness. No climbing permit and no overnight backcountry permit, but camping below 6,000 ft on this route is prohibited, which is the practical reason Crag View exists where it does. A recreation pass is required to park at the Park Butte trailhead. Party size is capped at 12 once you enter the wilderness, campfires are prohibited, and there is no toilet anywhere on the route — carry blue bags, which are handed out free at the ranger offices in Sedro-Woolley and at Glacier. Nothing may be buried in snow or dropped into a crevasse or moat.", "capacity": "The established climbers'' camp on the Squak, with room for several parties on gravel benches and snow platforms at the toe of the glacier; quieter than the Easton side even on a summer weekend"}, {"elev": 7000, "name": "Upper Squak benches, Sulphur moraine and the rock prow", "type": "bivy", "notes": "Parties who want Sherman''s summit day short move above Crag View and camp on the Sulphur moraine at the glacier''s edge around 7,000 ft, or push on to the flatter ground below the rock prow closer to 7,600 ft. The gain is real, since it takes a good chunk out of the traverse to the south ridge and puts you at the base of the steep snow with the night''s freeze still holding. The cost is a fully exposed camp on a volcano''s south flank, where wind is the usual reason parties come back down to Crag View, and you are already on glacier and roped to get here. Camping this high also means committing to melt water, which drives fuel weight up. Where exactly the platforms are usable moves year to year with the crevasse pattern, so arrive with daylight to scout rather than in the dark.", "water": "None. Melt snow. Anything running here in early summer is a bonus and will not be there later in the year.", "permit": "Mount Baker Wilderness rules as at Crag View — no permit to camp, recreation pass at the Park Butte trailhead, 12-person party limit, no campfires, all waste packed out in blue bags.", "capacity": "Dug snow platforms and moraine gravel for one or two parties along the right-hand edge of the glacier, with a second bench under a rock prow several hundred feet higher; no established sites and no shelter"}]'::jsonb WHERE id = 'wa_sherman_peak_baker_squak_glacier';

-- wa_sherman_peak_baker_squak_glacier: loss_ft filled in (was null) to match gain_ft (6800) -- this route approaches and descends via the same Schriebers Meadow / Park Butte Trailhead as the sibling Easton Glacier route (approach_logistics.trailheadLat/Lng identical: 48.7067849,-121.8129229), and descent_text describes reversing the ascent back to the same camp/trailhead, i.e. a genuine round trip.
UPDATE routes SET loss_ft = 6800 WHERE id = 'wa_sherman_peak_baker_squak_glacier';

-- wa_sherman_peak_baker_squak_glacier: emergency.nearestHospital filled in (was null), copied verbatim from the sibling wa_sherman_peak_baker_route, which shares the identical trailhead coordinates (Schriebers Meadow / Park Butte Trailhead) and therefore the identical nearest-hospital answer.
UPDATE routes SET emergency = jsonb_set(emergency, '{nearestHospital}', '"PeaceHealth St. Joseph Medical Center, Haggen Family Emergency and Trauma Center (Level II Trauma Center), Bellingham, WA \u2014 roughly a 2-2.5 hour drive from the Park Butte Trailhead"'::jsonb) WHERE id = 'wa_sherman_peak_baker_squak_glacier';

-- wa_sherpa_balanced_rock_ne_couloir (Northeast Couloir): bivy pruned 8->4. Removed four entries for entirely different peaks reached from different trailheads: 'Beverly and De Roux campgrounds' (explicitly for Ingalls Peak: 'This is what most parties on Ingalls Peak actually use'), 'Lake Caroline and Little Caroline' (explicitly for Cashmere Mountain: 'Cashmere Mountain does not belong to the Stuart Lake, Snow Lakes or Teanaway approaches at all'), 'Nada Lake' (explicitly the base for Cannon Mountain / Enchantment Peak / Witches Tower), and 'Argonaut north basin bivies' (explicitly 'this camp serves only Argonaut's north side'). Kept the four entries that explicitly name Sherpa Peak, two of which explicitly claim to serve this route's Northeast Couloir directly.
UPDATE routes SET bivy = '[{"name": "Ingalls Creek valley camps below the Sherpa and Argonaut south sides", "type": "camp", "notes": "This is the base for the south side of both Argonaut and Sherpa, and it is what makes those peaks feasible as overnights rather than brutal single pushes. Two ways in. From Esmeralda you climb to Longs Pass at about 6,200 feet and drop roughly 1,400 feet to the valley, then walk east along the trail until you are under your peak; Sherpa''s south basin is about a mile down, Argonaut''s exit gully perhaps three. From the low trailhead off US 97 you walk in flat but far, upwards of ten miles to reach the same ground, which trades the pass for distance and suits a party with time. A third link comes over Fourth Creek from the Beverly Creek trailhead in the Teanaway and requires fording Ingalls Creek, which is genuinely dangerous in June. The valley is low and sheltered, so it is buggy through midsummer and warm at night, and the brush between the trail and the open slopes above is the real work of the approach. Sites are dispersed rather than built, so pick an existing one instead of clearing new ground. The elevation of the trail changes across the several miles covered here, so no single figure is given.", "water": "Ingalls Creek runs strongly all season and side streams come in from the north wall; the only dry stretch is the climb over Longs Pass, which carries no water at all in either direction", "permit": "Alpine Lakes Wilderness under the Cle Elum Ranger District, entirely OUTSIDE the Enchantment Permit Area. A free self-issued wilderness permit from the trailhead box covers day and overnight use, there is no lottery, no quota and no reservation. A Northwest Forest Pass or day fee is needed to park at Esmeralda; the low Ingalls Creek trailhead off US 97 has its own parking requirement. Campfires are restricted seasonally and are a poor idea in any case; the valley is dry and forested. Camp at least 200 feet from the creek.", "capacity": "Numerous flat, well-used sites strung along several miles of valley floor and its side creeks; there is no quota and no realistic crowding, so a party can nearly always find its own ground"}, {"elev": 6200, "name": "Sherpa south basin camp", "type": "camp", "notes": "Sitting a couple of thousand feet above the Ingalls Creek trail in the cirque south of Sherpa, this is where a party wanting a reasonable summit day on the East or West Ridge sleeps. Getting here means leaving the valley trail and grinding up open slopes and gullies with no path to speak of, so the climb from the creek is the crux of the day rather than the ridge. The payoff is that the East Ridge start is an easy morning from here instead of a pre-dawn thrash. It is also the natural base for the Northeast Couloir on Sherpa Balanced Rock, which is reached by continuing up the basin to the notch east of the balanced block. Ground is a mix of scree and low heather and level spots take some hunting; the basin is open and catches wind.", "water": "Snowmelt streams draining the basin are reliable into midsummer and thin out by September; late-season parties should fill on the way up from Ingalls Creek rather than assume", "permit": "Cle Elum Ranger District, Alpine Lakes Wilderness, outside the Enchantment Permit Area. Free self-issued trailhead permit for day and overnight use, no lottery, no quota. Northwest Forest Pass at Esmeralda. No campfires at this elevation, and pitch on gravel or bare rock rather than on the meadow.", "capacity": "A small number of established spots on gravel and heather benches; two parties is comfortable, three is crowded"}, {"elev": 7400, "name": "Table Rock bivy, upper Sherpa basin", "type": "bivy", "notes": "A large flat block high in the basin below Sherpa''s south side, used by parties who want the East Ridge to start within minutes of waking rather than an hour and a half above camp. From here the route climbs a broad gully trending north-northeast to gain the crest east of the balanced rock, then follows blocks and sandy benches west past the block to the summit. It is exposed, windy and cold compared with the basin camp a thousand feet lower, and whether the extra height is worth carrying water up for is a real judgement call rather than an obvious yes. Anyone attempting Sherpa Balanced Rock''s Northeast Couloir gets the most from this position, since the couloir tops out close by. Leave no trace of a platform; the rock is bare and the ground around it is fragile.", "water": "None dependable. Snow patches persist into midsummer and can be melted, but treat it as a dry bivy and carry water up from the basin below.", "permit": "Cle Elum Ranger District, free self-issued Alpine Lakes Wilderness permit, no Enchantment lottery involved. Northwest Forest Pass at Esmeralda if you came over Longs Pass. No fires, and nothing here to build one with.", "capacity": "Two to four people on flat rock; this is a perch rather than a campsite, and there is nothing else level nearby"}, {"elev": 5400, "name": "Upper Mountaineer Creek bench", "type": "camp", "notes": "The north-side base for everything on this side of the range: the Sherpa Glacier and Sherpa''s north routes, Argonaut''s north approaches, and the start of the northeast ridge on Cannon Mountain. Leave the Stuart Lake trail at the first switchback where it begins to climb, roughly half a mile past the Colchuck Lake junction, and follow the creek up on its right for three to four miles on a rough climbers path. The bench at this elevation is the obvious flat ground and everyone stops there. Road access is the seasonal constraint: Forest Road 7601 off Icicle Creek Road is gated through winter and typically does not open until well into spring, which shortens the north-side season considerably compared with the Teanaway. Snow lingers in this basin, which is exactly why the couloir routes above are early-season objectives.", "water": "Mountaineer Creek runs beside the camp all season and is easy to draw from where the channel is open; in early season find a spot where the creek is running clear of snow", "permit": "This is the ambiguous one and it matters. The Stuart Lake trailhead sits inside the Enchantment Permit Area, and the Stuart Zone requires an overnight permit from May 15 through October 31, drawn either through the February advance lottery on the federal reservation system or through the daily lottery run from Leavenworth. Where the zone boundary falls in the upper Mountaineer Creek basin above the lakes is not clearly drawn on any public map, and reasonable people read it differently. Do not guess. Call the Wenatchee River Ranger District before the trip, and if you cannot get an answer, carry a Stuart Zone permit. Day use anywhere in the permit area needs only the free self-issued slip at the trailhead. Dogs are prohibited throughout the permit area and campfires are banned.", "capacity": "Plenty of good spots spread along the bench near the creek; several parties can spread out without seeing each other"}]'::jsonb WHERE id = 'wa_sherpa_balanced_rock_ne_couloir';

-- wa_sherpa_glacier (Mount Stuart): watch_out converted from a newline-delimited string to a proper JSON array (matching the shape every other hazard-style field on this row uses), and 'Class 4 glacier and ice climbing with crevasse hazard' corrected to 'Class 3' -- this row's own corrections field already documents fixing grade/grade_num/rock_grade from Class 4 to Class 3 on 2026-07-31 'matching this route's own overview text and SummitPost' (overview says 'class-3 ridge scrambling', beta says 'short class-3 scramble'), but watch_out was missed in that earlier pass and still described the old Class 4 rating.
UPDATE routes SET watch_out = '["Class 3 glacier and ice climbing with crevasse hazard", "Serac exposure and objective hazard present", "Route-finding through glacier terrain critical", "Altitude weather hazard (9,400+ ft)", "Early turnaround essential - sun softening increases hazard"]'::jsonb WHERE id = 'wa_sherpa_glacier';

-- wa_sherpa_glacier: waypoints[0] (Stuart Lake Trailhead) elev/elevFt corrected from 2930 to 3400 ft. Web search (WTA) confirms the Stuart Lake / Colchuck Lake Trailhead at the end of FR-7601 sits at 3,400 ft; the sibling route wa_sherpa_balanced_rock_ne_couloir independently states '~3,400 ft' for the identical trailhead coordinates in this batch. Triangulated further by this row's own gain_ft (6000, already fixed 2026-07-31 to match a logged 27-mi/6,000-ft trip): trailhead 3,400 ft to the summit waypoint (9,415 ft) nets 6,015 ft, matching gain_ft to within 15 ft, whereas the stored 2,930 ft gives 6,485 ft, a 485 ft mismatch. The stored value was the error.
UPDATE routes SET waypoints = jsonb_set(jsonb_set(waypoints, '{0,elev}', '3400'::jsonb), '{0,elevFt}', '3400'::jsonb) WHERE id = 'wa_sherpa_glacier';

-- wa_sherpa_glacier: approach_logistics.trailheadDirection's '~3,540 ft' corrected to '~3,400 ft' for internal consistency with the waypoint fix above and the confirmed real-world trailhead elevation.
UPDATE routes SET approach_logistics = jsonb_set(approach_logistics, '{trailheadDirection}', '"From the Stuart Lake Trailhead (end of FR-7601 off Icicle Creek Road, ~3,400 ft), via the Mountaineer Creek drainage"'::jsonb) WHERE id = 'wa_sherpa_glacier';

-- wa_sherpa_peak_east_ridge: bivy pruned 8->4, identical corridor-contamination pattern as wa_sherpa_balanced_rock_ne_couloir above (same four foreign-peak entries removed: Ingalls Peak campgrounds, Cashmere Mountain's Lake Caroline, Cannon Mountain's Nada Lake, and Argonaut's north-side-only basin).
